        // 源数据里有极少数 carrier_code 重复（同名承运商在多个国家出现），
        // carrier_code 在表里是唯一键，这里按 carrier_code 去重，保留首次出现的一条。
        $data = collect($carriers)
            ->unique('carrier_code')
            ->map(fn ($carrier) => array_merge($carrier, [
                'status' => 'enabled',
                'created_at' => $now,
                'updated_at' => $now,
            ]))
            ->values()
            ->all();

        // upsert 而非 insert：seeder 可能重复执行（部署/补数据），按 carrier_code 冲突时
        // 只刷新名称、国家、状态，不覆盖 pp_supported —— 那是后台超管手动维护的字段，
        // 不能被重新跑 seeder 悄悄重置回默认值。
        foreach (array_chunk($data, 200) as $chunk) {
            DB::table('carriers')->upsert(
                $chunk,
                ['carrier_code'],
                ['carrier_name', 'country_code', 'country_name', 'status', 'updated_at']
            );
        }
    }
